'use strict';

// MODULES //

var arraylike2object = require( '@stdlib/array/base/arraylike2object' );
var accessors = require( './accessors.js' );


// MAIN //

/**
* Computes the cross product of two input strided arrays and assigns the results to an output strided array.
*
* @param {NumericArray} x - first input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {NumericArray} y - second input array
* @param {integer} strideY - stride length for `y`
* @param {NonNegativeInteger} offsetY - starting index for `y`
* @param {NumericArray} z - output array
* @param {integer} strideZ - stride length for `z`
* @param {NonNegativeInteger} offsetZ - starting index for `z`
* @returns {NumericArray} output array
*
* @example
* var x = [ 1.0, 2.0, 3.0 ];
* var y = [ 4.0, 5.0, 6.0 ];
* var z = [ 0.0, 0.0, 0.0 ];
*
* gcross( x, 1, 0, y, 1, 0, z, 1, 0 );
* // z => [ -3.0, 6.0, -3.0 ]
*/
function gcross( x, strideX, offsetX, y, strideY, offsetY, z, strideZ, offsetZ ) {
	var ox;
	var oy;
	var oz;
	var x0;
	var x1;
	var x2;
	var y0;
	var y1;
	var y2;

	ox = arraylike2object( x );
	oy = arraylike2object( y );
	oz = arraylike2object( z );
	if ( ox.accessorProtocol || oy.accessorProtocol || oz.accessorProtocol ) {
		accessors( ox, strideX, offsetX, oy, strideY, offsetY, oz, strideZ, offsetZ );
		return z;
	}

	// Cache array elements...
	x0 = x[ offsetX ];
	x1 = x[ offsetX+strideX ];
	x2 = x[ offsetX+(2*strideX) ];
	y0 = y[ offsetY ];
	y1 = y[ offsetY+strideY ];
	y2 = y[ offsetY+(2*strideY) ];

	// Resolve cross product...
	z[ offsetZ ] = (x1*y2) - (x2*y1);
	z[ offsetZ+strideZ ] = (x2*y0) - (x0*y2);
	z[ offsetZ+(2*strideZ) ] = (x0*y1) - (x1*y0);

	return z;
}


// EXPORTS //

module.exports = gcross;
